-- Estructura de tabla para la tabla `auditoria_resoluciones`


CREATE TABLE `auditoria_resoluciones` (
  `id_auditoria` int(11) NOT NULL,
  `id_resolucion_eliminada` int(11) DEFAULT NULL,
  `fecha_eliminacion` datetime DEFAULT NULL,
  `usuario_eliminacion` varchar(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Estructura de tabla para la tabla `casos`


CREATE TABLE `casos` (
  `id_caso` int(11) NOT NULL,
  `id_juzgado` int(11) NOT NULL,
  `id_tipo_caso` int(11) NOT NULL,
  `fecha_inicio` date NOT NULL,
  `estado` varchar(50) NOT NULL DEFAULT 'INICIADO',
  `descripcion` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


